// The answers as a CSV file the person saves, one row an answer, after a row of headings.
const cell = (value) => '"' + String(value).split('"').join('""') + '"';
document.querySelector("[data-hook~=file-save]").addEventListener("click", async () => {
  const said = document.getElementById("saved");
  const rows = [["Name", "How many people", "Food allergies"]].concat(
    state.data.answers.map((answer) => [answer.name, answer.people, answer.allergies]),
  );
  const text = rows.map((row) => row.map(cell).join(",")).join(String.fromCharCode(10));
  try {
    const saved = await tessera.saveFile({ name: "party-answers.csv", type: "text/csv", text });
    said.textContent = saved ? "The answers are saved." : "Nothing was saved.";
  } catch (error) {
    said.textContent = error.message;
  }
});
